do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('arrive_active_route_stop','arrive_route_stop','complete_active_route_stop_after_evidence','complete_route','create_offline_pack','create_route_plan','populate_route_discovery_cache','prepare_route_discovery','queue_offline_pack_event','record_favorite_route_event','record_location_route_event') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
